--
-- Table structure for table `tb_devices`
--

CREATE TABLE `tb_devices` (
  `id_device` bigint(20) UNSIGNED NOT NULL,
  `id_room` bigint(20) UNSIGNED NOT NULL,
  `device_name` varchar(100) NOT NULL,
  `device_code` varchar(100) NOT NULL,
  `device_type` enum('LAMP','AC','PROJECTOR') NOT NULL,
  `status` enum('ON','OFF','UNKNOWN') NOT NULL DEFAULT 'OFF',
  `is_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `last_seen_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `id_controller` bigint(20) UNSIGNED DEFAULT NULL,
  `relay_channel` varchar(100) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

