--
-- Table structure for table `tb_device_commands`
--

CREATE TABLE `tb_device_commands` (
  `id_command` bigint(20) UNSIGNED NOT NULL,
  `id_device` bigint(20) UNSIGNED NOT NULL,
  `id_user` bigint(20) UNSIGNED DEFAULT NULL,
  `command` enum('ON','OFF') NOT NULL,
  `source` enum('AUTO','MANUAL','ADMIN') NOT NULL,
  `command_status` enum('PENDING','SUCCESS','FAILED') NOT NULL DEFAULT 'PENDING',
  `error_message` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `executed_at` datetime DEFAULT NULL,
  `claimed_at` datetime DEFAULT NULL,
  `claim_token_hash` char(64) DEFAULT NULL
